// Single source of truth for "what events do we have right now."
// Both the listing route (/api/events), the detail page (/events/[id]), and
// the ICS endpoint import this function so they see the exact same event
// set. That guarantees a hash ID generated by the listing always resolves
// on the detail page — no more 404s when clicking through.

import { unstable_cache } from "next/cache"
import { scrapeCerebralValley, type ScrapedEvent } from "@/lib/scrapers/cerebralvalley"
import { scrapeLuma } from "@/lib/scrapers/luma"
import { filterReachable } from "@/lib/validators/links"
import { isSpecificEventUrl } from "@/lib/validators/specific-urls"
import { parseLocation } from "@/lib/geo/parse"

export type { ScrapedEvent }

// Pipe a scraped event through parseLocation so it carries city/region/lat/lng.
// Mutates safely — only writes into fields the scraper left empty.
function enrichGeo(e: ScrapedEvent): ScrapedEvent {
  const parsed = parseLocation(e.location ?? null)
  if (!parsed) return e
  return {
    ...e,
    isVirtual: e.isVirtual || parsed.isVirtual,
    venue:   e.venue   ?? parsed.venue,
    city:    e.city    ?? parsed.city,
    region:  e.region  ?? parsed.region,
    state:   e.state   ?? parsed.state,
    country: e.country ?? parsed.country,
    lat:     e.lat     ?? parsed.lat,
    lng:     e.lng     ?? parsed.lng,
  }
}

export function stableEventId(url: string): string {
  let h = 0
  for (let i = 0; i < url.length; i++) {
    h = ((h << 5) - h) + url.charCodeAt(i)
    h |= 0
  }
  return `ev-${Math.abs(h).toString(36)}`
}

// Bump the version suffix to invalidate when scraper output shape changes.
const CACHE_KEY = "events-shared-v6-luma-real-city"
const CACHE_TTL_SECONDS = 1800

// Cross-source dedupe: same event posted on CV + Luma should appear once.
// Key = lowercased title + ISO date. CV is listed first so it wins ties
// (richer description, cover image).
function dedupeAcrossSources(events: ScrapedEvent[]): ScrapedEvent[] {
  const byUrl = new Set<string>()
  const byTitleDay = new Set<string>()
  const out: ScrapedEvent[] = []
  for (const e of events) {
    if (byUrl.has(e.registrationUrl)) continue
    const day = new Date(e.startDate).toISOString().slice(0, 10)
    const titleKey = `${e.title.toLowerCase().trim()}|${day}`
    if (byTitleDay.has(titleKey)) continue
    byUrl.add(e.registrationUrl)
    byTitleDay.add(titleKey)
    out.push(e)
  }
  return out
}

// CITY-AGNOSTIC by design. The Luma scraper already pulls from multiple city
// pages internally (sf, nyc, discover, plus named community calendars), so
// the broad set covers everything. Caching at a single key — no city arg —
// means listing + detail + ICS all share the same data → IDs always match.
export const getAllEvents = unstable_cache(
  async (): Promise<ScrapedEvent[]> => {
    const [cvResult, lumaResult] = await Promise.allSettled([
      scrapeCerebralValley(),
      scrapeLuma("networking tech startup"),
    ])

    const cv = cvResult.status === "fulfilled" ? cvResult.value : []
    const lu = lumaResult.status === "fulfilled" ? lumaResult.value : []

    // Reject community/discovery URLs — only specific event pages.
    const specific = [...cv, ...lu].filter((e) =>
      isSpecificEventUrl(e.registrationUrl),
    )

    const deduped = dedupeAcrossSources(specific)

    // Validate URLs are actually reachable
    const reachable = await filterReachable(deduped, (e) => e.registrationUrl)

    // Enrich with structured geo (city / region / lat / lng) so the listing
    // API and the frontend proximity engine never need to re-parse strings.
    return reachable.map(enrichGeo)
  },
  [CACHE_KEY],
  { revalidate: CACHE_TTL_SECONDS, tags: ["events"] },
)

// Back-compat alias for the old signature. Ignores the city argument — the
// underlying cache is now city-agnostic. Callers should migrate to getAllEvents.
export const getEventsForLocation = async (_city: string | null) => getAllEvents()
